// Four choices authored together for every question. No cross-item distractor pool.
const quizEditorialSets=[];
const quizTopicFamilies={'Immobilisation par attelle':'Attelle','Pansement et bandage':'Bandage','Suture':'Aiguille et fil de suture','Extraction d’un corps étranger':'Forceps / pince'};
let quizBankCache=null;
function buildQuizBank(){
 if(quizBankCache)return quizBankCache;
 const bank=[];
 for(const [group,content] of quizEditorialSets)for(const line of content.trim().split('\n')){
  const fields=line.split('|').map(value=>value.trim());
  if(fields.length!==7)throw Error('Invalid editorial row: '+line);
  const [reference,prompt,correct,...tail]=fields,explanation=tail.pop(),pool=tail;
  if(new Set([correct,...pool]).size!==4)throw Error('Duplicate choices: '+prompt);
  bank.push({id:group+':'+bank.length,topic:quizTopicFamilies[reference]||reference,group,reference,prompt,correct,pool,explanation});
 }
 quizBankCache=bank;return bank;
}
